------------ define ------------

------------ define ------------


---@class GrowthFundLevelRewardNode
---@field FinishMark                    	UnityEngine.RectTransform
---@field FontStyleButton               	UnityEngine.RectTransform
---@field MonthFundLock                 	UnityEngine.RectTransform
---@field GoodNode3                     	Engine.Modules.LuaBehaviour
---@field GoodNode2                     	Engine.Modules.LuaBehaviour
---@field GoodNode1                     	Engine.Modules.LuaBehaviour
---@field TxtLevel                      	UnityEngine.RectTransform
local GrowthFundLevelRewardNode = Class("GrowthFundLevelRewardNode")
function GrowthFundLevelRewardNode:__init()
    self.isPurchased = nil
    self.id = nil--奖励的配表id

end

function GrowthFundLevelRewardNode:__delete()
    self.controller = nil
    self.isPurchased = nil
    self.id = nil

end

---SetCallBack
---设置单击回调函数--领取奖励
function GrowthFundLevelRewardNode:SetCallBack(cb)
    self.__callback = cb
end

function GrowthFundLevelRewardNode:Awake()
    UIEventProxy.Create(self.FontStyleButton.gameObject).onPointerClick = function()
        if type(self.__callback) == 'function' then
            self.__callback()
        end
    end
    if isNull(self.GoodNode1.Env) then
        self.GoodNode1:Init()
    end
    if isNull(self.GoodNode2.Env) then
        self.GoodNode2:Init()
    end
    if isNull(self.GoodNode3.Env) then
        self.GoodNode3:Init()
    end
end

function GrowthFundLevelRewardNode:FreshBaseUI(vo, getStatus, isPurchased)
    self.isPurchased = isPurchased
    self.id = vo.id
    CfUtils.FillText(self.TxtLevel, vo.PlayerLv)
    --前两个免费奖励
    local freeRewardsId = string.split(vo.freeRewardId, ";")
    local freeRewardsNum = string.split(vo.freeRewardNum, ";")
    KTool.SetActive(self.GoodNode2, #freeRewardsId > 1)
    for i = 1, #freeRewardsId do
        self["GoodNode"..i].Env:SetClickButtonAction(function()
            local vo = GoodsConfMgr:GetInstance():GetGoodsVoById(freeRewardsId[i])
            if isTable(vo) then
                GameUtils.ShowCommonTipsBoard(self["GoodNode"..i].gameObject, vo.name, vo.desc, vo.quality, vo.id)
            end
        end)
        self["GoodNode"..i].Env:Reload(
                {
                    goodsId = freeRewardsId[i],
                    isShowNo = true, text = 'x' .. tostring(freeRewardsNum[i])
                }
        )
    end
    --第三个付费奖励
    KTool.SetActive(self.MonthFundLock, not isPurchased)
    local ChargeRewardId = vo.ChargeRewardId
    local ChargeRewardNum = vo.ChargeRewardNum
    self.GoodNode3.Env:SetClickButtonAction(function(i)
        local vo = GoodsConfMgr:GetInstance():GetGoodsVoById(ChargeRewardId)
        if isTable(vo) then
            GameUtils.ShowCommonTipsBoard(self.GoodNode3.gameObject, vo.name, vo.desc, vo.quality, vo.id)
        end
    end)
    self.GoodNode3.Env:Reload(
            {
                goodsId = ChargeRewardId,
                isShowNo = true, text = 'x' .. tostring(ChargeRewardNum)
            }
    )
    self:FreshGetStatus(getStatus)
end

function GrowthFundLevelRewardNode:FreshGetStatus(status)
    status = checkInt(status)
    local hasGet = status == Constants.GetStatus.Has --已领取
    local canGet = status == Constants.GetStatus.Can
    local playerComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.PlayerComponent)
    local freePayLevelRewards = playerComponent.playerDojo.freePayLevelRewards--免费基金奖励
    local paidPayLevelRewards = playerComponent.playerDojo.paidPayLevelRewards--收费基金奖励
    KTool.SetActive(self.FinishMark, hasGet)
    KTool.SetActive(self.FontStyleButton, not hasGet)
    if status == Constants.GetStatus.Can then
        self.FontStyleButton:GetComponent(typeof(FontStyleButton)):ResetFontStyle("B12", localize("领取"))
    elseif status == Constants.GetStatus.Not then
        self.FontStyleButton:GetComponent(typeof(FontStyleButton)):ResetFontStyle("B13", localize("未达成"))
    end
    local freeHasGet = self:HasGetReward(freePayLevelRewards, self.id)
    local paidHasGet = self:HasGetReward(paidPayLevelRewards, self.id)
    self.GoodNode1.Env:SetSanXingGainShow(freeHasGet)--
    self.GoodNode2.Env:SetSanXingGainShow(freeHasGet)--
    self.GoodNode3.Env:SetSanXingGainShow(paidHasGet)
    self.GoodNode1.Env:SetCanGetEffectShow((not freeHasGet) and canGet)--
    self.GoodNode2.Env:SetCanGetEffectShow((not freeHasGet) and canGet)--
    self.GoodNode3.Env:SetCanGetEffectShow(canGet and self.isPurchased)
end

---是否领过了奖励
---@param list table 服务器的奖励领取列表
---@param rewardId number 奖励Id
function GrowthFundLevelRewardNode:HasGetReward(list, rewardId)
    rewardId = checkString(rewardId)
    if table.keyof(list, rewardId) ~= nil then
        return true
    else
        return false
    end
end

function GrowthFundLevelRewardNode:OnDestroy()
    self.controller = nil --删除lua层引用到的c#对象 否则不会产生c# gc回收到对象
    self:Delete()
    self = nil --lua层的gc需要
end

return GrowthFundLevelRewardNode